const D = { energy:.6, scale:1, density:.5, speed:1, floors:.5, hue:28, x:.5, y:.46, style:'section', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const h1 = n => { const s = Math.sin(n*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const fr = (i,j) => h1(i*57.3 + j*131.9 + 7.1);
const vn1 = x => { const i=Math.floor(x), f2=x-i, w=f2*f2*(3-2*f2); return h1(i)*(1-w) + h1(i+1)*w; };
const fbm1 = x => .55*vn1(x) + .28*vn1(x*2.1+7.3) + .17*vn1(x*4.3-3.1);

const sty = P.style;
const bp = (sty==='blueprint'), geo = (sty==='geological'), xr = (sty==='xray'), riso = (sty==='riso');
const H = ((P.hue%360)+360)%360;
const NCv = Math.max(2, Math.round(3 + P.density*6));
const cw = Math.ceil(width/NCv);
const PAD = Math.round(height*.30), BH = height + PAD*2;
const GY = PAD + height*.46;                                  // grade line inside the buffer
const NF = Math.max(1, Math.round(2 + cl(P.floors,0,1)*5));   // storeys
const fh = height*.098*cl(P.scale,.35,2.2);                   // storey height
const st = Math.max(2, height*.010*cl(P.scale,.35,2.2));      // slab thickness

// ---- real-time truck across an endless section; content keyed on abs column -
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.px = (S.px||0) + dt * P.speed * cw * .17 * (.6 + .5*K.intensity) * (.6 + .6*P.energy);
const pan = S.px + cl(P.x,0,1)*width*2;
const c0 = Math.floor(pan/cw), off = pan - c0*cw;

const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const glow = (.38 + .62*P.energy)*(.55 + .5*K.intensity) + bass*.3;
// slow incommensurate vertical camera lift — a second non-repeating motion axis
const camY = PAD*.60*P.energy*(.55*Math.sin(K.t*.041) + .30*Math.sin(K.t*.113+1.4) + .15*Math.sin(K.t*.267+.6));
const yoff = -PAD + camY + (cl(P.y,.30,.64) - .46)*height;

// ---- palette ----------------------------------------------------------------
const T = {};
if (bp){
  T.sky=[212,64,17]; T.air=[212,62,22]; T.poche=[212,20,86]; T.room=[212,60,24];
  T.slab=[212,40,52]; T.soil=[212,58,28]; T.rock=[212,64,19]; T.ink=[196,26,100]; T.win=[186,30,96];
} else if (geo){
  T.sky=[198,28,72]; T.air=[198,18,82]; T.poche=[0,0,14]; T.room=[40,7,66];
  T.slab=[0,0,38]; T.soil=[26,62,44]; T.rock=[16,52,26]; T.ink=[24,52,16]; T.win=[46,70,96];
} else if (xr){
  T.sky=[H,44,5]; T.air=[H,40,7]; T.poche=[H,34,24]; T.room=[H,52,9];
  T.slab=[H,38,16]; T.soil=[H,48,10]; T.rock=[H,52,7]; T.ink=[H,22,98]; T.win=[H,18,100];
} else if (riso){
  T.sky=[38,7,92]; T.air=[38,5,95]; T.poche=[338,74,70]; T.room=[38,4,90];
  T.slab=[212,66,60]; T.soil=[338,40,86]; T.rock=[212,52,56]; T.ink=[338,72,58]; T.win=[46,66,96];
} else {
  T.sky=[H+180,18,60]; T.air=[H+180,10,70]; T.poche=[H,24,10]; T.room=[H,9,70];
  T.slab=[H,16,30]; T.soil=[H-6,34,30]; T.rock=[H-12,22,18]; T.ink=[H,28,16]; T.win=[H+8,44,94];
}
for (const k2 in T) T[k2][0] = ((T[k2][0]%360)+360)%360;
const cf = (g,c,a) => g.fill(((c[0]%360)+360)%360, cl(c[1],0,100), cl(c[2],0,100), a==null?100:a);
const cs = (g,c,a,w) => { g.stroke(((c[0]%360)+360)%360, cl(c[1],0,100), cl(c[2],0,100), a==null?100:a); g.strokeWeight(Math.max(.7, w||1)); };

// strata boundaries in world coords — continuous across every column seam
const strat = [[.055,.030],[.125,.038],[.245,.052],[.400,.060]];
const syOf = (k,wx) => GY + strat[k][0]*height + strat[k][1]*height*(fbm1(wx/(u*.75) + k*13.7) - .5)*2;

// ---- one column of the section, baked once ---------------------------------
function buildCol(ci){
  const g = createGraphics(cw, BH); g.pixelDensity(1);
  g.colorMode(HSB,360,100,100,100); g.noStroke();
  const wx0 = ci*cw, wins = [];
  const roofY = GY - NF*fh;

  // sky: gradient down to the horizon haze
  const NG = 22;
  for (let i=0;i<NG;i++){ const s=i/(NG-1);
    cf(g, [T.sky[0], T.sky[1] + (T.air[1]-T.sky[1])*s, T.sky[2] + (T.air[2]-T.sky[2])*s]);
    g.rect(0, BH*i/NG - 1, cw, BH/NG + 2);
  }

  // ---- earth: five strata, top down --------------------------------------
  const bands = [T.soil,
                 [T.soil[0]-4, T.soil[1]*.82, T.soil[2]*1.20],
                 [T.soil[0]-10, T.soil[1]*.58, T.soil[2]*.82],
                 [T.rock[0], T.rock[1]*.9, T.rock[2]*1.30],
                 T.rock];
  for (let k=0;k<5;k++){
    const c = bands[k];
    cf(g, geo ? [c[0] + k*26, cl(48 + k*5,0,90), cl(60 - k*8,8,90)] : c);
    g.noStroke(); g.beginShape();
    for (let i=0;i<=8;i++){ const wx = wx0 + cw*i/8; g.vertex(cw*i/8, k===0 ? GY : syOf(k-1, wx)); }
    for (let i=8;i>=0;i--){ const wx = wx0 + cw*i/8; g.vertex(cw*i/8, k<4 ? syOf(k, wx) : BH); }
    g.endShape(CLOSE);
    if (xr && k>0){ cs(g, T.ink, 24, 1); g.noFill(); g.beginShape();
      for (let i=0;i<=8;i++){ const wx=wx0+cw*i/8; g.vertex(cw*i/8, syOf(k-1,wx)); } g.endShape(); g.noStroke(); }
  }

  // stratum textures
  if (!bp && !xr){
    cs(g, T.ink, 44, 1);                                       // topsoil roots & tufts
    for (let i=0;i<Math.round(cw/9);i++){ const lx2 = fr(ci*3+i,1)*cw, hh = 3 + fr(ci*3+i,2)*height*.020;
      g.line(lx2, GY+2, lx2 + (fr(ci*3+i,3)-.5)*8, GY+2 - hh);
      g.line(lx2, GY+2, lx2 + (fr(ci*3+i,7)-.5)*10, GY+2 + hh*.7);
    }
    g.noStroke();                                              // gravel pebbles
    for (let i=0;i<Math.round(cw/6);i++){ const lx2 = fr(ci*11+i,4)*cw, wx = wx0 + lx2;
      const a2 = syOf(1,wx), b2 = syOf(2,wx), yy = a2 + fr(ci*11+i,5)*(b2-a2);
      const rad = 1.4 + fr(ci*11+i,6)*height*.006;
      cf(g, geo ? [46,32,84] : [T.soil[0]+6, T.soil[1]*.5, cl(T.soil[2]*1.7,0,96)]);
      g.ellipse(lx2, yy, rad*2, rad*1.4);
    }
    cs(g, [T.soil[0], T.soil[1]*.6, cl(T.soil[2]*(geo?.5:1.5),0,96)], 40, 1);  // clay bedding
    for (let i=0;i<7;i++){ const q=(i+.5)/7; g.noFill(); g.beginShape();
      for (let j=0;j<=8;j++){ const wx = wx0 + cw*j/8;
        g.vertex(cw*j/8, syOf(2,wx) + q*(syOf(3,wx)-syOf(2,wx))); }
      g.endShape(); }
    cs(g, [T.rock[0], T.rock[1]*.5, cl(T.rock[2]*(geo?.45:2.0),0,96)], 34, 1); // bedrock fractures
    for (let i=0;i<5;i++){ const lx2 = fr(ci*17+i,8)*cw, wx = wx0 + lx2;
      const y0 = syOf(3,wx) + fr(ci*17+i,9)*(BH - syOf(3,wx))*.5;
      g.line(lx2, y0, lx2 + (fr(ci*17+i,10)-.5)*cw*.5, y0 + fr(ci*17+i,11)*height*.14);
    }
  }
  if (riso){                                                   // halftone plate over the earth
    g.noStroke(); const dp = Math.max(6, height*.018);
    for (let yy = GY; yy < BH; yy += dp){ const d2 = cl((yy-GY)/(height*.55),0,1);
      for (let xx = 0; xx < cw; xx += dp){
        cf(g, [212, 62, 54], 62); g.ellipse(xx, yy, dp*(.18+.52*d2), dp*(.18+.52*d2)); } }
  }

  // ---- service tunnel bore (longitudinal section) -------------------------
  const ty = GY + height*.315, th2 = height*.055;
  cf(g, xr ? [T.room[0],T.room[1],T.room[2]*2.2] : T.poche); g.noStroke(); g.rect(0, ty-th2*.5-2, cw, th2+4);
  cf(g, bp ? T.room : (xr ? [H,50,4] : [T.poche[0], T.poche[1]*.6, cl(T.poche[2]*1.9+2,2,70)]));
  g.rect(0, ty-th2*.5+2, cw, th2-4);
  cs(g, T.ink, 60, 1.2); g.noFill();
  g.line(0, ty-th2*.5, cw, ty-th2*.5); g.line(0, ty+th2*.5, cw, ty+th2*.5);
  for (let i=0;i<4;i++){ const lx2 = cw*(i+.5)/4; g.line(lx2, ty-th2*.5+2, lx2, ty+th2*.5-2); }
  cs(g, T.win, 70, 2); g.line(0, ty+th2*.34, cw, ty+th2*.34);

  // ---- buried services ----------------------------------------------------
  cs(g, T.ink, 70, Math.max(1.4, height*.005));  g.line(0, GY + height*.045, cw, GY + height*.048);
  cs(g, T.win, 46, Math.max(1, height*.003));    g.line(0, GY + height*.082, cw, GY + height*.080);

  // ---- the building -------------------------------------------------------
  for (let j=0;j<NF;j++){
    const fy = GY - (j+1)*fh;
    g.noStroke(); cf(g, T.room); g.rect(0, fy, cw, fh);
    if (fr(ci*5+j,12) > .2){                                   // back-wall window
      const ww = cw*(.30 + fr(ci*5+j,13)*.34), wh = fh*.42;
      const wx2 = cw*.1 + fr(ci*5+j,14)*(cw*.8 - ww), wy = fy + fh*.16;
      cf(g, [T.win[0], T.win[1]*.5, T.win[2]*.7]); g.rect(wx2, wy, ww, wh);
      cs(g, T.ink, 70, 1.2); g.noFill(); g.rect(wx2, wy, ww, wh);
      g.line(wx2+ww*.5, wy, wx2+ww*.5, wy+wh);
      wins.push([wx2, wy, ww, wh, fr(ci*5+j,15)*6.283]);
    }
    g.noStroke();                                              // abstract furnishing blocks
    const nb = 1 + Math.floor(fr(ci*5+j,16)*3);
    for (let b=0;b<nb;b++){
      const bw = cw*(.06 + fr(ci*7+j*3+b,17)*.14), bh2 = fh*(.12 + fr(ci*7+j*3+b,18)*.42);
      const bx = cw*.06 + fr(ci*7+j*3+b,19)*(cw*.88 - bw);
      cf(g, [T.poche[0], T.poche[1]*.8, cl(T.poche[2]*(riso?1.0:2.4)+8, 3, 88)]);
      g.rect(bx, fy + fh - bh2, bw, bh2);
    }
    if (fr(ci*5+j,20) > .62){                                  // a stair run to the storey above
      cs(g, T.ink, 76, 1.2); g.noFill();
      const n2 = 7, sx0 = cw*.60, sy0 = fy + fh, sw2 = cw*.32;
      for (let i2=0;i2<n2;i2++){ const q=i2/n2, q2=(i2+1)/n2;
        g.line(sx0+sw2*q, sy0-fh*q, sx0+sw2*q2, sy0-fh*q);
        g.line(sx0+sw2*q2, sy0-fh*q, sx0+sw2*q2, sy0-fh*q2); }
    }
    g.noStroke(); cf(g, T.slab); g.rect(0, fy - st*.5, cw, st);  // slab (poché)
  }
  cf(g, T.slab); g.rect(0, GY - st*.5, cw, st*1.3);
  cf(g, T.slab); g.rect(0, roofY - st*.9, cw, st*1.5);
  cf(g, T.poche); g.rect(0, roofY - fh*.16, Math.max(3, cw*.05), fh*.16);   // parapet
  if (fr(ci,21) > .45){                                        // roof plant
    const tw = cw*(.10 + fr(ci,22)*.14), thh = fh*(.22 + fr(ci,24)*.24);
    cf(g, [T.poche[0], T.poche[1]*.7, cl(T.poche[2]*2.2+6, 3, 80)]);
    g.rect(cw*.2 + fr(ci,23)*cw*.5, roofY - thh, tw, thh);
  }
  for (let q=0;q<2;q++){                                       // structure + footings + piles
    const lx2 = q*cw*.5, colW = Math.max(2.4, cw*.030);
    cf(g, T.poche); g.rect(lx2-colW*.5, roofY, colW, GY-roofY);
    cf(g, [T.poche[0], T.poche[1], cl(T.poche[2]*1.5, 2, 60)]);
    g.rect(lx2-colW*1.6, GY, colW*3.2, height*.022);
    g.rect(lx2-colW*.55, GY, colW*1.1, height*.10);
  }
  cs(g, T.ink, 90, Math.max(1.4, height*.0028)); g.line(0, GY, cw, GY);     // the cut
  if (riso){                                                   // second ink plate, misregistered
    g.blendMode(MULTIPLY); g.noStroke(); cf(g, [212, 68, 62], 46);
    for (let q=0;q<2;q++){ const lx2 = q*cw*.5, colW = Math.max(2.4, cw*.030);
      g.rect(lx2-colW*.5+3.5, roofY-2.5, colW, GY-roofY); }
    g.rect(0, GY-3, cw, Math.max(1.6, height*.003));
    g.blendMode(BLEND);
  }
  return { g: g, wins: wins, used: 0 };
}

// ---- cache ------------------------------------------------------------------
const ck = [width,height,sty,Math.round(H),sd,NCv,NF,Math.round(fh),Math.round(st)].join('|');
if (S.ck !== ck){
  if (S.cols) for (const k2 in S.cols){ try { S.cols[k2].g.remove(); } catch(e){} }
  S.cols = {}; S.ck = ck;
}
noStroke(); fill(T.air[0], T.air[1], T.air[2], 100); rect(0,0,width,height);
let budget = 4;
const lw = [];
for (let i=-1; i<=NCv+1; i++){
  const ci = c0 + i, sx = i*cw - off;
  if (sx > width || sx + cw < 0) continue;
  let col = S.cols[ci];
  if (!col){ if (budget-- <= 0) continue; col = S.cols[ci] = buildCol(ci); }
  col.used = K.t;
  image(col.g, sx, yoff);
  for (let w=0; w<col.wins.length; w++) lw.push([sx, col.wins[w], ci*31.7 + w]);
}
for (const k2 in S.cols){
  if (K.t - S.cols[k2].used > 4 && Math.abs((+k2) - c0) > NCv + 3){
    try { S.cols[k2].g.remove(); } catch(e){} delete S.cols[k2];
  }
}

// ---- live: lit windows breathing, a light running the tunnel ---------------
push(); blendMode(ADD); noStroke();
for (let i=0;i<lw.length;i++){
  const sx = lw[i][0], w = lw[i][1], q = lw[i][2];
  const fl = .30 + .70*(.5 + .5*Math.sin(K.t*.23 + q*1.7))*(.5 + .5*Math.sin(K.t*.61 + q));
  fill(T.win[0], cl(T.win[1]*.7,0,100), 100, cl(4 + 22*glow*fl, 0, 36));
  rect(sx + w[0], yoff + w[1], w[2], w[3]);
  fill(T.win[0], cl(T.win[1]*.5,0,100), 100, cl(1.6 + 6*glow*fl, 0, 12));
  rect(sx + w[0] - w[2]*.3, yoff + w[1] - w[3]*.3, w[2]*1.6, w[3]*1.6);
}
const tvx = ((K.t*.055*P.speed + .13) % 1) * width*1.6 - width*.3;
const tvy = yoff + GY + height*.315;
for (let i=3;i>=1;i--){ fill(T.win[0], 30, 100, 2.4 + 5*glow); ellipse(tvx, tvy, u*.06*i, height*.03*i); }
pop(); blendMode(BLEND);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
